-- 6. Books
('p1000000-0000-0000-0000-000000000026', 'Atomic Habits by James Clear (Hardcover)', 'atomic-habits-james-clear', 'An easy and proven way to build good habits and break bad ones. Over 15 million copies sold worldwide. Transform your daily routines with tiny changes.', 'Random House', 'c1000000-0000-0000-0000-000000000006', 899, 599, 200, ARRAY['https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&q=80'], '{"Format": "Hardcover", "Pages": "320", "Language": "English", "ISBN-13": "978-0735211292"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000027', 'The Psychology of Money by Morgan Housel', 'the-psychology-of-money-morgan-housel', 'Timeless lessons on wealth, greed, and happiness. Doing well with money isn''t necessarily about what you know. It''s about how you behave.', 'Harriman House', 'c1000000-0000-0000-0000-000000000006', 499, 349, 180, ARRAY['https://images.unsplash.com/photo-1592496431122-2349e0fbc666?w=800&q=80'], '{"Format": "Paperback", "Pages": "256", "Language": "English", "ISBN-13": "978-9390166268"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000028', 'Designing Data-Intensive Applications by Martin Kleppmann', 'designing-data-intensive-applications', 'The definitive guide to the architecture of reliable, scalable, and maintainable systems. Key principles of databases, distributed systems, and pipelines.', 'O''Reilly Media', 'c1000000-0000-0000-0000-000000000006', 2499, 1999, 60, ARRAY['https://images.unsplash.com/photo-1532012164546-f432f2e3777a?w=800&q=80'], '{"Format": "Paperback", "Pages": "616", "Language": "English", "Publisher": "O''Reilly Media"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000029', 'Deep Work: Rules for Focused Success by Cal Newport', 'deep-work-cal-newport', 'Deep work is the ability to focus without distraction on a cognitively demanding task. A skill that allows you to quickly master complicated information.', 'Grand Central', 'c1000000-0000-0000-0000-000000000006', 699, 489, 95, ARRAY['https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&q=80'], '{"Format": "Paperback", "Pages": "304", "Language": "English", "Subject": "Productivity & Focus"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000030', 'Thinking, Fast and Slow by Daniel Kahneman', 'thinking-fast-and-slow-daniel-kahneman', 'Major New York Times bestseller by Nobel Prize winner in Economics Daniel Kahneman on the two systems that drive the way we think and decide.', 'Farrar, Straus and Giroux', 'c1000000-0000-0000-0000-000000000006', 799, 520, 110, ARRAY['https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&q=80'], '{"Format": "Paperback", "Pages": "512", "Language": "English", "Award": "Nobel Laureate"}'::jsonb, true),

