('p1000000-0000-0000-0000-000000000037', 'Kiehl''s Ultra Facial Cream with Squalane 50ml', 'kiehls-ultra-facial-cream-50ml', '24-hour daily lightweight facial moisturizer. Formulated with Glacial Glycoprotein and olive-derived Squalane for intensely hydrated, softer skin.', 'Kiehl''s', 'c1000000-0000-0000-0000-000000000008', 3400, 2850, 65, ARRAY['https://images.unsplash.com/photo-1556228720-195a672e8a03?w=800&q=80'], '{"Skin Type": "All Skin Types", "Key Ingredients": "Squalane, Glacial Glycoprotein", "Texture": "Lightweight Cream", "Volume": "50 ml"}'::jsonb, true),
