('p1000000-0000-0000-0000-000000000039', 'The Ordinary Niacinamide 10% + Zinc 1% 60ml', 'the-ordinary-niacinamide-zinc-60ml', 'High-strength vitamin and mineral blemish formula. Reduces the appearance of blemishes, balances visible sebum activity, and smooths skin texture.', 'The Ordinary', 'c1000000-0000-0000-0000-000000000008', 1200, 890, 150, ARRAY['https://images.unsplash.com/photo-1608248597359-bb4fc225ef54?w=800&q=80'], '{"Target": "Oiliness, Blemishes, Uneven Texture", "Key Actives": "10% Niacinamide, 1% Zinc PCA", "Volume": "60 ml"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000040', 'Philips Norelco Multigroom 9000 All-in-One Trimmer', 'philips-norelco-multigroom-9000', '25-piece men''s grooming kit for beard, hair, body and face. Self-sharpening DualCut steel blades and lithium-ion battery with 6 hours run time.', 'Philips', 'c1000000-0000-0000-0000-000000000008', 7499, 5499, 48, ARRAY['https://images.unsplash.com/photo-1621607512214-68297480165e?w=800&q=80'], '{"Battery": "Lithium-Ion (6 Hours)", "Blades": "DualCut Steel", "Guards": "14 reinforced trimming guards", "Waterproof": "Fully washable"}'::jsonb, true),

-- 9. Accessories
('p1000000-0000-0000-0000-000000000041', 'Seiko Presage Cocktail Time Automatic Watch', 'seiko-presage-cocktail-time-automatic', 'Inspired by the glamour of cocktail lounges. Sunburst guilloché dial with box-shaped Hardlex crystal, exhibition case back, and 4R35 automatic movement.', 'Seiko', 'c1000000-0000-0000-0000-000000000009', 42500, 36900, 18, ARRAY['https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=800&q=80'], '{"Movement": "Caliber 4R35 Automatic", "Power Reserve": "41 Hours", "Case Diameter": "40.5 mm", "Strap": "Brown Calfskin Leather"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000042', 'Bellroy Hide & Seek RFID Blocking Leather Wallet', 'bellroy-hide-and-seek-leather-wallet', 'Slim profile bi-fold wallet made from premium certified environmentally tanned leather. Hidden coin and bill compartment with protected RFID protection.', 'Bellroy', 'c1000000-0000-0000-0000-000000000009', 7999, 6499, 70, ARRAY['https://images.unsplash.com/photo-1627123424574-724758594e93?w=800&q=80'], '{"Capacity": "5-12+ cards", "Leather": "LWG certified premium hide", "RFID": "Protection built-in", "Dimensions": "8.5 x 11.5 cm"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000043', 'Peak Design Everyday Backpack 20L V2 Charcoal', 'peak-design-everyday-backpack-20l', 'Iconic, multi-award-winning pack for everyday carry and photo gear. Features MagLatch hardware, weatherproof 400D nylon canvas shell, and FlexFold dividers.', 'Peak Design', 'c1000000-0000-0000-0000-000000000009', 28990, 24490, 15, ARRAY['https://images.unsplash.com/photo-1546938576-6e6a64f317cc?w=800&q=80'], '{"Volume": "20 Liters", "Laptop Carry": "Up to 15 inch", "Shell": "Weatherproof 400D Recycled Nylon", "Warranty": "Lifetime"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000044', 'Tom Ford Snowdon Classic Wayfarer Sunglasses', 'tom-ford-snowdon-wayfarer-sunglasses', 'Distinctive thick acetate sunglasses with signature gold-tone metal T temple logos. 100% UVA/UVB protection with iconic Italian craftsmanship.', 'Tom Ford', 'c1000000-0000-0000-0000-000000000009', 34500, 27900, 12, ARRAY['https://images.unsplash.com/photo-1508296695146-257a814070b4?w=800&q=80'], '{"Frame": "Glossy Dark Havana Acetate", "Lens": "Brown 100% UV", "Hardware": "Signature Shiny Metal T", "Origin": "Italy"}'::jsonb, true),
('p1000000-0000-0000-0000-000000000045', 'Fossil Grant Chronograph Dark Brown Leather Watch', 'fossil-grant-chronograph-leather-watch', 'Roman numeral indexes set against a sunray blue dial, stopwatch function with three sub-dials, stainless steel case, and interchangeable genuine leather band.', 'Fossil', 'c1000000-0000-0000-0000-000000000009', 12995, 8995, 45, ARRAY['https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800&q=80'], '{"Case Size": "44 mm", "Movement": "Quartz Chronograph", "Water Resistance": "50 m (5 ATM)", "Strap Width": "22 mm"}'::jsonb, true)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  brand = EXCLUDED.brand,
  price = EXCLUDED.price,
  discount_price = EXCLUDED.discount_price,
  stock_quantity = EXCLUDED.stock_quantity,
  image_urls = EXCLUDED.image_urls,
  specifications = EXCLUDED.specifications,
  is_active = EXCLUDED.is_active;

-- Sample Reviews
INSERT INTO public.reviews (id, product_id, user_id, rating, comment, created_at)
SELECT 
  gen_random_uuid(),
  p.id,
  '00000000-0000-0000-0000-000000000001'::uuid,
  5,
  'Absolute top quality! Delivered fast in Mumbai, pristine packaging, completely original product.',
  now() - interval '3 days'
FROM public.products p
ON CONFLICT DO NOTHING;

INSERT INTO public.reviews (id, product_id, user_id, rating, comment, created_at)
SELECT 
  gen_random_uuid(),
  p.id,
  '00000000-0000-0000-0000-000000000002'::uuid,
  4,
  'Great value for money. Built very solidly and performs exactly as specified.',
  now() - interval '6 days'
FROM public.products p
WHERE p.price > 10000
ON CONFLICT DO NOTHING;

